var a=`0793-mkatra-foutra`;var n=`world-0793`;var i=`KM`;var o=`eastern-africa`;var s=8;var r=109;var u={en:`Mkatra Foutra`,ua:`Мкатра футра`};var l={en:`Mkatra Foutra is a Comoros classic prepared with all-purpose flour, coconut milk, instant yeast, desiccated coconut. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Мкатра футра, страва кухні країни Коморські Острови зі складниками: пшеничне борошно універсальне, кокосове молоко, інстантні дріжджі, кокосова стружка. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 70 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 70 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:70,i:[[`all-purpose-flour`,460,`g`],[`coconut-milk`,280,`ml`],[`instant-yeast`,7,`g`],[`white-granulated-sugar`,50,`g`],[`table-salt`,5,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 24 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 24 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:24,i:[[`sunflower-oil`,45,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`desiccated-coconut`,40,`g`]]}];var g={slug:a,id:n,country:`KM`,region:o,servings:8,minutes:109,title:u,text:l,steps:d};export{i as country,g as default,n as id,r as minutes,o as region,s as servings,a as slug,d as steps,l as text,u as title};